&lt;div class="highlight js-code-highlight"&gt;
&lt;pre class="highlight plaintext"&gt;&lt;code&gt;        &amp;lt;Route path="/" element={&amp;lt;Home /&amp;gt;} /&amp;gt;

&amp;lt;Route path="/about" element={&amp;lt;About /&amp;gt;} /&amp;gt;

